    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of participants
        int n = scanner.nextInt();
        scanner.nextLine(); // consume newline

        List<Participant> participants = new ArrayList<>();

        // Read each participant's data
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            String[] parts = line.split(" ");

            // First part is student ID, rest are scores for 10 frames
            String id = parts[0];
            int[] scores = new int[10];
            for (int j = 0; j < 10; j++) {
                scores[j] = Integer.parseInt(parts[j + 1]);
            }

            participants.add(new Participant(id, scores));
        }

        // Sort by score descending, then by ID ascending
        Collections.sort(participants, (a, b) -> {
            if (a.totalScore != b.totalScore) {
                return b.totalScore - a.totalScore; // descending by score
            }
            return a.id.compareTo(b.id); // ascending by ID
        });

        // Output results
        for (Participant p : participants) {
            System.out.println(p.id + " " + p.totalScore);
        }

        scanner.close();
    }

    static class Participant {
        String id;
        int totalScore;

        Participant(String id, int[] frameScores) {
            this.id = id;
            this.totalScore = calculateScore(frameScores);
        }

        private int calculateScore(int[] rolls) {
            // Standard bowling scoring
            int total = 0;
            int rollIndex = 0;

            for (int frame = 0; frame < 10; frame++) {
                if (rolls[rollIndex] == 10) { // Strike
                    total += 10 + rolls[rollIndex + 1] + rolls[rollIndex + 2];
                    rollIndex++;
                } else if (rolls[rollIndex] + rolls[rollIndex + 1] == 10) { // Spare
                    total += 10 + rolls[rollIndex + 2];
                    rollIndex += 2;
                } else { // Open frame
                    total += rolls[rollIndex] + rolls[rollIndex + 1];
                    rollIndex += 2;
                }
            }

            return total;
        }
    }
}

